-- Рейсы: даты — ближайшие две недели от 2026-11-12
INSERT INTO flights
    (flight_number, airline_id, from_airport_id, to_airport_id, departure_date, departure_time, arrival_time, duration_minutes, transfers, price, seats_total, seats_left, cabin, baggage)
SELECT v.flight_number, a.id, fa.id, ta.id, v.departure_date, v.departure_time, v.arrival_time, v.duration_minutes, v.transfers, v.price, v.seats_total, v.seats_left, v.cabin, v.baggage
FROM (
    SELECT 'DP 6502' flight_number, 'DP' airline_code, 'UFA' from_code, 'VKO' to_code, DATE_ADD('2026-11-12', INTERVAL n.d DAY) departure_date, '07:20' departure_time, '09:25' arrival_time, 125 duration_minutes, 0 transfers, 4290.00 price, 180 seats_total, 4 seats_left, 'Эконом' cabin, 'Ручная кладь 10 кг' baggage FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'SU 1234', 'SU', 'UFA', 'SVO', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '10:35', '12:45', 130, 0, 7840.00, 158, 7, 'Эконом', 'Багаж 23 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'UT 364', 'UT', 'UFA', 'VKO', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '16:50', '19:05', 135, 0, 5120.00, 120, 2, 'Эконом', 'Ручная кладь 10 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'S7 3510', 'S7', 'UFA', 'DME', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '12:15', '14:35', 140, 0, 6750.00, 158, 12, 'Эконом', 'Багаж 23 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'UT 575', 'UT', 'UFA', 'AER', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '10:10', '12:55', 165, 0, 6190.00, 120, 9, 'Эконом', 'Ручная кладь 10 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'N4 211', 'N4', 'UFA', 'AER', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '14:40', '17:25', 165, 0, 7430.00, 220, 18, 'Эконом', 'Багаж 23 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'SU 6408', 'SU', 'UFA', 'LED', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '09:05', '11:30', 145, 0, 5490.00, 158, 5, 'Эконом', 'Багаж 23 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'A4 702', 'A4', 'UFA', 'LED', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '18:30', '21:00', 150, 0, 4980.00, 120, 14, 'Эконом', 'Ручная кладь 10 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'TK 428', 'TK', 'UFA', 'IST', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '06:40', '10:20', 220, 0, 18700.00, 180, 21, 'Эконом', 'Багаж 23 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'SU 1683', 'SU', 'UFA', 'IST', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '15:55', '19:35', 220, 0, 22150.00, 158, 11, 'Эконом', 'Багаж 23 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'WZ 336', 'WZ', 'VKO', 'UFA', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '20:10', '00:15', 185, 0, 4650.00, 120, 8, 'Эконом', 'Ручная кладь 10 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'UT 359', 'UT', 'VKO', 'UFA', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '11:40', '15:45', 185, 0, 5320.00, 120, 16, 'Эконом', 'Ручная кладь 10 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'UT 576', 'UT', 'AER', 'UFA', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '13:30', '17:20', 170, 0, 6190.00, 120, 13, 'Эконом', 'Ручная кладь 10 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
    UNION ALL SELECT 'SU 6409', 'SU', 'LED', 'UFA', DATE_ADD('2026-11-12', INTERVAL n.d DAY), '12:40', '17:10', 150, 0, 5490.00, 158, 6, 'Эконом', 'Багаж 23 кг' FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13) n
) v
JOIN airlines a ON a.code = v.airline_code
JOIN airports fa ON fa.code = v.from_code
JOIN airports ta ON ta.code = v.to_code
WHERE NOT EXISTS (
    SELECT 1 FROM flights f
    WHERE f.flight_number = v.flight_number AND f.departure_date = v.departure_date
);
